	(12, 1, '2026-08-29 10:25:33', '2026-08-29 10:25:33', '<!-- wp:group {"align":"full","layout":{"type":"default"}} -->\n<div class="wp-block-group alignfull"><!-- wp:html -->\n<style data-wp-block-html="css">\n:root {\n        --bg-dark: #0d0204;\n        --velvet-main: #1f050b;\n        --velvet-card: #2c0710;\n        --gold: #d4af37;\n        --gold-light: #f3e5ab;\n        --gold-dark: #aa8528;\n        --text-light: #f5e8e8;\n        --text-muted: #c4a1a8;\n        --border-gold: rgba(212, 175, 55, 0.35);\n    }\n    body { margin:0; }\n    .cart-page-section {\n        background: radial-gradient(circle at 50% 0%, var(--velvet-main) 0%, var(--bg-dark) 100%);\n        color: var(--text-light);\n        font-family: \'Montserrat\', sans-serif;\n        padding: 60px 4% 100px 4%;\n        min-height: 80vh;\n        width: 100%;\n        box-sizing: border-box;\n    }\n    .cart-container { max-width: 1400px; margin: 0 auto; width: 100%; }\n    .cart-header { text-align: center; margin-bottom: 45px; }\n    .section-kicker { font-size: 0.85rem; letter-spacing: 3px; text-transform: uppercase; color: var(--gold); display: block; margin-bottom: 8px; font-weight: 600; }\n    .cart-main-title {\n        font-family: \'Cormorant Garamond\', serif;\n        font-size: 3.2rem; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; margin: 0;\n        background: linear-gradient(135deg, #ffffff 0%, var(--gold-light) 60%, var(--gold) 100%);\n        -webkit-background-clip: text; -webkit-text-fill-color: transparent;\n    }\n    .title-divider { width: 80px; height: 2px; background: linear-gradient(90deg, transparent, var(--gold), transparent); margin: 18px auto 0 auto; }\n    .cart-grid { display: grid; grid-template-columns: 1fr 420px; gap: 40px; align-items: start; }\n    .cart-left-col { display: flex; flex-direction: column; gap: 35px; }\n    .cart-card { background: linear-gradient(145deg, var(--velvet-card) 0%, rgba(20, 3, 7, 0.95) 100%); border: 1px solid var(--border-gold); border-radius: 12px; padding: 35px 40px; box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5); }\n    .card-section-title { font-family: \'Cormorant Garamond\', serif; font-size: 1.8rem; color: var(--gold-light); margin: 0 0 25px 0; display: flex; align-items: center; gap: 12px; letter-spacing: 1px; }\n    .title-icon { width: 26px; height: 26px; fill: var(--gold); }\n    .cart-items-list { display: flex; flex-direction: column; gap: 20px; }\n    .cart-item { display: grid; grid-template-columns: 90px 1fr auto auto; gap: 25px; align-items: center; padding-bottom: 20px; border-bottom: 1px solid rgba(212, 175, 55, 0.15); }\n    .cart-item:last-child { border-bottom: none; padding-bottom: 0; }\n    .cart-item-img { width: 60px; height: 70px; object-fit: contain; background-color: transparent; }\n    .cart-item-details h3 { font-family: \'Cormorant Garamond\', serif; font-size: 1.4rem; color: #fff; margin: 0 0 4px 0; }\n    .cart-item-sub { font-size: 0.85rem; color: var(--text-muted); margin: 0 0 6px 0; }\n    .cart-item-unit-price { font-size: 0.9rem; color: var(--gold-light); }\n    .qty-selector-sm { display: flex; align-items: center; border: 1px solid var(--border-gold); border-radius: 6px; background: rgba(13, 2, 4, 0.6); overflow: hidden; height: 38px; }\n    .qty-btn-sm { background: none; border: none; color: var(--gold-light); width: 32px; height: 100%; font-size: 1.1rem; cursor: pointer; transition: background 0.2s; }\n    .qty-btn-sm:hover { background: rgba(212, 175, 55, 0.2); }\n    .qty-input-sm { width: 40px; background: none; border: none; text-align: center; color: #fff; font-size: 0.95rem; font-weight: 600; }\n    .cart-item-right { display: flex; align-items: center; gap: 25px; }\n    .cart-item-total { font-family: \'Cormorant Garamond\', serif; font-size: 1.5rem; font-weight: 700; color: var(--gold-light); min-width: 100px; text-align: right; }\n    .btn-remove-item { background: none; border: none; color: var(--text-muted); cursor: pointer; padding: 5px; transition: color 0.2s; display: flex; align-items: center; }\n    .btn-remove-item:hover { color: #ff5555; }\n    .btn-remove-item svg { width: 20px; height: 20px; fill: currentColor; }\n    .empty-cart-msg { text-align: center; padding: 40px 20px; }\n    .empty-cart-msg p { font-size: 1.1rem; color: var(--text-muted); margin-bottom: 20px; }\n    .btn-gold-secondary { display: inline-block; border: 1px solid var(--gold); color: var(--gold-light); padding: 10px 24px; border-radius: 30px; text-decoration: none; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 1px; transition: all 0.3s ease; }\n    .btn-gold-secondary:hover { background: var(--gold); color: var(--bg-dark); }\n    .options-group { margin-bottom: 25px; }\n    .options-group:last-child { margin-bottom: 0; }\n    .option-title { display: block; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 1.5px; color: var(--gold-light); margin-bottom: 12px; font-weight: 600; }\n    .options-grid { display: flex; flex-direction: column; gap: 12px; }\n    .option-card { display: flex; align-items: center; justify-content: space-between; background: rgba(13, 2, 4, 0.5); border: 1px solid var(--border-gold); border-radius: 8px; padding: 16px 20px; cursor: pointer; transition: all 0.3s ease; }\n    .option-card:hover { border-color: var(--gold); background: rgba(88, 12, 29, 0.2); }\n    .option-card input[type="radio"] { accent-color: var(--gold); margin-right: 14px; width: 18px; height: 18px; }\n    .option-info { display: flex; flex-direction: column; flex: 1; }\n    .option-name { font-size: 0.95rem; color: #fff; font-weight: 500; }\n    .option-sub { font-size: 0.8rem; color: var(--text-muted); }\n    .option-price { font-size: 0.95rem; font-weight: 600; color: var(--gold-light); }\n    .option-price.highlight { color: #4cd964; }\n    .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }\n    .form-group { display: flex; flex-direction: column; margin-bottom: 18px; }\n    .form-group label { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); margin-bottom: 6px; }\n    .form-group input, .form-group textarea { background: rgba(13, 2, 4, 0.6); border: 1px solid var(--border-gold); border-radius: 6px; padding: 12px 16px; color: #fff; font-family: \'Montserrat\', sans-serif; font-size: 0.95rem; outline: none; transition: border-color 0.3s ease; }\n    .form-group input:focus, .form-group textarea:focus { border-color: var(--gold); box-shadow: 0 0 10px rgba(212, 175, 55, 0.2); }\n    .form-checkbox { display: flex; align-items: flex-start; gap: 10px; margin-top: 10px; }\n    .form-checkbox input[type="checkbox"] { accent-color: var(--gold); width: 18px; height: 18px; margin-top: 2px; }\n    .form-checkbox label { font-size: 0.85rem; color: var(--text-muted); line-height: 1.5; cursor: pointer; }\n    .summary-card { background: linear-gradient(145deg, var(--velvet-card) 0%, rgba(30, 4, 10, 0.95) 100%); border: 1px solid var(--gold); border-radius: 12px; padding: 35px; box-shadow: 0 10px 30px rgba(212, 175, 55, 0.15); position: sticky; top: 20px; }\n    .summary-title { font-family: \'Cormorant Garamond\', serif; font-size: 1.8rem; color: var(--gold-light); margin: 0 0 20px 0; letter-spacing: 1px; }\n    .promo-code-box { display: flex; gap: 8px; margin-bottom: 8px; }\n    .promo-code-box input { flex: 1; background: rgba(13, 2, 4, 0.6); border: 1px solid var(--border-gold); border-radius: 6px; padding: 10px 12px; color: #fff; font-size: 0.85rem; text-transform: uppercase; }\n    .btn-apply-promo { background: transparent; border: 1px solid var(--gold); color: var(--gold-light); padding: 0 16px; border-radius: 6px; cursor: pointer; font-size: 0.8rem; text-transform: uppercase; font-weight: 600; transition: all 0.3s ease; }\n    .btn-apply-promo:hover { background: var(--gold); color: var(--bg-dark); }\n    .promo-message { font-size: 0.78rem; margin-bottom: 20px; min-height: 18px; }\n    .promo-message.success { color: #4cd964; }\n    .promo-message.error { color: #ff5555; }\n    .summary-rows { display: flex; flex-direction: column; gap: 12px; margin-bottom: 20px; }\n    .summary-row { display: flex; justify-content: space-between; font-size: 0.95rem; color: var(--text-muted); }\n    .gold-text { color: var(--gold); font-weight: 600; }\n    .summary-divider { height: 1px; background: linear-gradient(90deg, transparent, var(--border-gold), transparent); margin: 15px 0; }\n    .summary-total-box { display: flex; flex-direction: column; margin-bottom: 25px; }\n    .total-label { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-muted); }\n    .total-amount { font-family: \'Cormorant Garamond\', serif; font-size: 3rem; font-weight: 700; color: var(--gold-light); line-height: 1.1; }\n    .total-vat-info { font-size: 0.75rem; color: var(--text-muted); }\n    .btn-checkout { width: 100%; background: linear-gradient(135deg, var(--gold) 0%, var(--gold-dark) 100%); color: var(--bg-dark); border: none; border-radius: 6px; font-size: 0.95rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; padding: 16px; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 10px; transition: all 0.3s ease; box-shadow: 0 4px 15px rgba(212, 175, 55, 0.3); }\n    .btn-checkout:hover { background: linear-gradient(135deg, #e5c158 0%, var(--gold) 100%); transform: translateY(-2px); box-shadow: 0 6px 20px rgba(212, 175, 55, 0.4); }\n    .btn-arrow { width: 20px; height: 20px; fill: var(--bg-dark); transition: transform 0.3s ease; }\n    .btn-checkout:hover .btn-arrow { transform: translateX(4px); }\n    .trust-badges { display: flex; justify-content: space-around; margin-top: 25px; padding-top: 20px; border-top: 1px dashed rgba(212, 175, 55, 0.2); }\n    .badge-item { display: flex; align-items: center; gap: 6px; font-size: 0.75rem; color: var(--text-muted); }\n    .badge-item svg { width: 16px; height: 16px; fill: var(--gold); }\n    @media (max-width: 1100px) { .cart-grid { grid-template-columns: 1fr 360px; gap: 25px; } }\n    @media (max-width: 960px) { .cart-grid { grid-template-columns: 1fr; } .summary-card { position: static; } }\n    @media (max-width: 600px) { .cart-card { padding: 20px 18px; } .cart-item { grid-template-columns: 60px 1fr; gap: 12px; } .cart-item-right { grid-column: 1 / -1; justify-content: space-between; } .form-row { grid-template-columns: 1fr; } }\n\n</style>\n\n<script data-wp-block-html="js">\nlet cart = [\n        {\n            id: \'medak-05\',\n            name: \'Medák 40% alc\',\n            subtitle: \'Medovicový nápoj • 0,5 l\',\n            price: 350,\n            quantity: 1,\n            image: \'https://raw.githubusercontent.com/Pahi25/Medak/refs/heads/main/Med%C3%A1k.png\'\n        }\n    ];\n \n    let appliedDiscount = 0;\n \n    document.addEventListener("DOMContentLoaded", function() {\n        renderCartItems();\n        updateCartTotals();\n    });\n \n    function renderCartItems() {\n        const container = document.getElementById(\'cartItemsList\');\n        const emptyMsg = document.getElementById(\'emptyCartMsg\');\n        const shippingSec = document.getElementById(\'shippingPaymentSection\');\n        const customerSec = document.getElementById(\'customerDetailsSection\');\n        const checkoutBtn = document.getElementById(\'submitOrderBtn\');\n \n        if (cart.length === 0) {\n            container.style.display = \'none\';\n            emptyMsg.style.display = \'block\';\n            shippingSec.style.opacity = \'0.5\';\n            shippingSec.style.pointerEvents = \'none\';\n            customerSec.style.opacity = \'0.5\';\n            customerSec.style.pointerEvents = \'none\';\n            checkoutBtn.disabled = true;\n            return;\n        }\n \n        container.style.display = \'flex\';\n        emptyMsg.style.display = \'none\';\n        shippingSec.style.opacity = \'1\';\n        shippingSec.style.pointerEvents = \'all\';\n        customerSec.style.opacity = \'1\';\n        customerSec.style.pointerEvents = \'all\';\n        checkoutBtn.disabled = false;\n \n        let html = \'\';\n        cart.forEach((item, index) => {\n            const itemTotal = item.price * item.quantity;\n            html += `\n                <div class="cart-item">\n                    <img src="${item.image}" alt="${item.name}" class="cart-item-img"\n                         onload="reportImgStatus(true, \'${item.image}\')"\n                         onerror="reportImgStatus(false, \'${item.image}\')">\n                    <div class="cart-item-details">\n                        <h3>${item.name}</h3>\n                        <p class="cart-item-sub">${item.subtitle}</p>\n                        <span class="cart-item-unit-price">${item.price} Kč / ks</span>\n                    </div>\n                    <div class="qty-selector-sm">\n                        <button type="button" class="qty-btn-sm" onclick="changeQty(${index}, -1)">-</button>\n                        <input type="number" class="qty-input-sm" value="${item.quantity}" readonly>\n                        <button type="button" class="qty-btn-sm" onclick="changeQty(${index}, 1)">+</button>\n                    </div>\n                    <div class="cart-item-right">\n                        <span class="cart-item-total">${itemTotal} Kč</span>\n                        <button type="button" class="btn-remove-item" onclick="removeItem(${index})" title="Odebrat z košíku">\n                            <svg viewBox="0 0 24 24"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg>\n                        </button>\n                    </div>\n                </div>\n            `;\n        });\n \n        container.innerHTML = html;\n    }\n \n    function changeQty(index, delta) {\n        if (cart[index]) {\n            cart[index].quantity += delta;\n            if (cart[index].quantity <= 0) {\n                cart.splice(index, 1);\n            }\n            renderCartItems();\n            updateCartTotals();\n        }\n    }\n \n    function removeItem(index) {\n        cart.splice(index, 1);\n        renderCartItems();\n        updateCartTotals();\n    }\n \n    function updateCartTotals() {\n        let subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);\n \n        const selectedShipping = document.querySelector(\'input[name="shipping"]:checked\');\n        const shippingPrice = selectedShipping ? parseInt(selectedShipping.getAttribute(\'data-price\')) : 0;\n \n        const selectedPayment = document.querySelector(\'input[name="payment"]:checked\');\n        const paymentPrice = selectedPayment ? parseInt(selectedPayment.getAttribute(\'data-price\')) : 0;\n \n        const discountAmount = Math.round(subtotal * appliedDiscount);\n        const totalPrice = Math.max(0, subtotal - discountAmount + shippingPrice + paymentPrice);\n \n        document.getElementById(\'summarySubtotal\').innerText = `${subtotal} Kč`;\n        document.getElementById(\'summaryShipping\').innerText = shippingPrice === 0 ? \'Zdarma\' : `${shippingPrice} Kč`;\n        document.getElementById(\'summaryPayment\').innerText = paymentPrice === 0 ? \'Zdarma\' : `${paymentPrice} Kč`;\n \n        const promoRow = document.getElementById(\'promoDiscountRow\');\n        if (appliedDiscount > 0) {\n            promoRow.style.display = \'flex\';\n            document.getElementById(\'summaryDiscount\').innerText = `-${discountAmount} Kč`;\n        } else {\n            promoRow.style.display = \'none\';\n        }\n \n        document.getElementById(\'summaryTotal\').innerText = `${totalPrice} Kč`;\n    }\n \n    function applyPromoCode() {\n        const input = document.getElementById(\'promoInput\').value.trim().toUpperCase();\n        const msg = document.getElementById(\'promoMessage\');\n \n        if (input === "MED10") {\n            appliedDiscount = 0.10;\n            msg.className = "promo-message success";\n            msg.innerText = "Slevový kód 10% byl úspěšně uplatněn!";\n        } else if (input === "") {\n            msg.innerText = "";\n        } else {\n            appliedDiscount = 0;\n            msg.className = "promo-message error";\n            msg.innerText = "Neplatný slevový kód.";\n        }\n        updateCartTotals();\n    }\n \n    function handleOrderSubmit(e) {\n        e.preventDefault();\n        if (cart.length === 0) {\n            alert("Váš košík je prázdný!");\n            return;\n        }\n        const formData = {\n            firstName: document.getElementById(\'firstName\').value,\n            lastName: document.getElementById(\'lastName\').value,\n            email: document.getElementById(\'email\').value,\n            phone: document.getElementById(\'phone\').value,\n            street: document.getElementById(\'street\').value,\n            city: document.getElementById(\'city\').value,\n            zip: document.getElementById(\'zip\').value,\n            note: document.getElementById(\'note\').value,\n            shipping: document.querySelector(\'input[name="shipping"]:checked\').value,\n            payment: document.querySelector(\'input[name="payment"]:checked\').value,\n            cart: cart\n        };\n        console.log("Objednávka k odeslání:", formData);\n        alert("Děkujeme za vaši objednávku! Byla úspěšně přijata.");\n        cart = [];\n        renderCartItems();\n        updateCartTotals();\n    }\n</script>\n\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="">\n<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,600;0,700;1,400&amp;family=Montserrat:wght@300;400;500;600;700&amp;display=swap" rel="stylesheet">\n\n<section class="cart-page-section">\n    <div class="cart-container">\n \n        <div class="cart-header">\n            <span class="section-kicker">Medárna Lískovec</span>\n            <h1 class="cart-main-title">Nákupní košík</h1>\n            <div class="title-divider"></div>\n        </div>\n \n        <div class="cart-grid">\n \n            <div class="cart-left-col">\n \n                <div class="cart-card">\n                    <h2 class="card-section-title">\n                        <svg class="title-icon" viewBox="0 0 24 24"><path d="M7 18c-1.1 0-1.99.9-1.99 2S5.9 22 7 22s2-.9 2-2-.9-2-2-2zM1 2v2h2l3.6 7.59-1.35 2.45c-.16.28-.25.61-.25.96 0 1.1.9 2 2 2h12v-2H7.42c-.14 0-.25-.11-.25-.25l.03-.12.9-1.63h7.45c.75 0 1.41-.41 1.75-1.03l3.58-6.49c.08-.14.12-.31.12-.48 0-.55-.45-1-1-1H5.21l-.94-2H1zm16 16c-1.1 0-1.99.9-1.99 2s.89 2 1.99 2 2-.9 2-2-.9-2-2-2z"></path></svg>\n                        Vybrané produkty\n                    </h2>\n \n                    <div id="cartItemsList" class="cart-items-list"></div>\n \n                    <div id="emptyCartMsg" class="empty-cart-msg" style="display: none;">\n                        <p>Váš košík je zatím prázdný.</p>\n                        <a href="index.html#produkt" class="btn-gold-secondary">Prohlédnout Medák</a>\n                    </div>\n                </div>\n \n                <div class="cart-card" id="shippingPaymentSection">\n                    <h2 class="card-section-title">\n                        <svg class="title-icon" viewBox="0 0 24 24"><path d="M20 8h-3V4H3c-1.1 0-2 .9-2 2v11h2c0 1.66 1.34 3 3 3s3-1.34 3-3h6c0 1.66 1.34 3 3 3s3-1.34 3-3h2v-5l-3-4zM6 18.5c-.83 0-1.5-.67-1.5-1.5s.67-1.5 1.5-1.5 1.5.67 1.5 1.5-.67 1.5-1.5 1.5zm13.5-9l1.96 2.5H17V9.5h2.5zm-1.5 9c-.83 0-1.5-.67-1.5-1.5s.67-1.5 1.5-1.5 1.5.67 1.5 1.5-.67 1.5-1.5 1.5z"></path></svg>\n                        Doprava a Platba\n                    </h2>\n \n                    <div class="options-group">\n                        <label class="option-title">1. Způsob doručení</label>\n                        <div class="options-grid">\n                            <label class="option-card active">\n                                <input type="radio" name="shipping" value="zasilkovna" data-price="89" checked="" onchange="updateCartTotals()">\n                                <div class="option-info">\n                                    <span class="option-name">Zásilkovna / Z-BOX</span>\n                                    <span class="option-sub">Doručení na výdejní místo</span>\n                                </div>\n                                <span class="option-price">89 Kč</span>\n                            </label>\n                            <label class="option-card">\n                                <input type="radio" name="shipping" value="kuryr" data-price="129" onchange="updateCartTotals()">\n                                <div class="option-info">\n                                    <span class="option-name">Kurýr na adresu</span>\n                                    <span class="option-sub">Doručení až k vám domů</span>\n                                </div>\n                                <span class="option-price">129 Kč</span>\n                            </label>\n                            <label class="option-card">\n                                <input type="radio" name="shipping" value="osobni" data-price="0" onchange="updateCartTotals()">\n                                <div class="option-info">\n                                    <span class="option-name">Osobní odběr</span>\n                                    <span class="option-sub">Lískovec u Frýdku-Místku</span>\n                                </div>\n                                <span class="option-price highlight">Zdarma</span>\n                            </label>\n                        </div>\n                    </div>\n \n                    <div class="options-group">\n                        <label class="option-title">2. Způsob platby</label>\n                        <div class="options-grid">\n                            <label class="option-card active">\n                                <input type="radio" name="payment" value="karta" data-price="0" checked="" onchange="updateCartTotals()">\n                                <div class="option-info">\n                                    <span class="option-name">Platební karta</span>\n                                    <span class="option-sub">Rychlá a bezpečná platba online</span>\n                                </div>\n                                <span class="option-price highlight">Zdarma</span>\n                            </label>\n                            <label class="option-card">\n                                <input type="radio" name="payment" value="prevod" data-price="0" onchange="updateCartTotals()">\n                                <div class="option-info">\n                                    <span class="option-name">Bankovní převod</span>\n                                    <span class="option-sub">Podklady zašleme do e-mailu</span>\n                                </div>\n                                <span class="option-price highlight">Zdarma</span>\n                            </label>\n                            <label class="option-card">\n                                <input type="radio" name="payment" value="dobirka" data-price="45" onchange="updateCartTotals()">\n                                <div class="option-info">\n                                    <span class="option-name">Dobírka</span>\n                                    <span class="option-sub">Platba při převzetí</span>\n                                </div>\n                                <span class="option-price">45 Kč</span>\n                            </label>\n                        </div>\n                    </div>\n                </div>\n \n                <div class="cart-card" id="customerDetailsSection">\n                    <h2 class="card-section-title">\n                        <svg class="title-icon" viewBox="0 0 24 24"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"></path></svg>\n                        Dodací údaje\n                    </h2>\n \n                    <form id="orderForm" onsubmit="handleOrderSubmit(event)">\n                        <div class="form-row">\n                            <div class="form-group">\n                                <label for="firstName">Jméno *</label>\n                                <input type="text" id="firstName" required="" placeholder="Jan">\n                            </div>\n                            <div class="form-group">\n                                <label for="lastName">Příjmení *</label>\n                                <input type="text" id="lastName" required="" placeholder="Novák">\n                            </div>\n                        </div>\n                        <div class="form-row">\n                            <div class="form-group">\n                                <label for="email">E-mail *</label>\n                                <input type="email" id="email" required="" placeholder="jan.novak@email.cz">\n                            </div>\n                            <div class="form-group">\n                                <label for="phone">Telefon *</label>\n                                <input type="tel" id="phone" required="" placeholder="+420 777 123 456">\n                            </div>\n                        </div>\n                        <div class="form-group">\n                            <label for="street">Ulice a číslo popisné *</label>\n                            <input type="text" id="street" required="" placeholder="Lískovecká 123">\n                        </div>\n                        <div class="form-row">\n                            <div class="form-group">\n                                <label for="city">Město *</label>\n                                <input type="text" id="city" required="" placeholder="Frýdek-Místek">\n                            </div>\n                            <div class="form-group">\n                                <label for="zip">PSČ *</label>\n                                <input type="text" id="zip" required="" placeholder="738 01">\n                            </div>\n                        </div>\n                        <div class="form-group">\n                            <label for="note">Poznámka k objednávce (nepovinné)</label>\n                            <textarea id="note" rows="3" placeholder="Instrukce k doručení..."></textarea>\n                        </div>\n                        <div class="form-checkbox">\n                            <input type="checkbox" id="ageCheck" required="">\n                            <label for="ageCheck">Potvrzuji, že je mi více než 18 let a souhlasím s obchodními podmínkami. *</label>\n                        </div>\n                    </form>\n                </div>\n \n            </div>\n \n            <div class="cart-right-col">\n                <div class="summary-card">\n                    <h3 class="summary-title">Shrnutí objednávky</h3>\n \n                    <div class="promo-code-box">\n                        <input type="text" id="promoInput" placeholder="Slevový kód">\n                        <button type="button" class="btn-apply-promo" onclick="applyPromoCode()">Použít</button>\n                    </div>\n                    <div id="promoMessage" class="promo-message"></div>\n \n                    <div class="summary-rows">\n                        <div class="summary-row"><span>Zboží celkem:</span><span id="summarySubtotal">0 Kč</span></div>\n                        <div class="summary-row"><span>Doprava:</span><span id="summaryShipping">89 Kč</span></div>\n                        <div class="summary-row"><span>Platba:</span><span id="summaryPayment">0 Kč</span></div>\n                        <div class="summary-row promo-row" id="promoDiscountRow" style="display: none;">\n                            <span>Sleva:</span><span id="summaryDiscount" class="gold-text">-0 Kč</span>\n                        </div>\n                    </div>\n \n                    <div class="summary-divider"></div>\n \n                    <div class="summary-total-box">\n                        <span class="total-label">Celkem k úhradě</span>\n                        <span class="total-amount" id="summaryTotal">0 Kč</span>\n                        <span class="total-vat-info">Včetně DPH</span>\n                    </div>\n \n                    <button type="submit" form="orderForm" class="btn-checkout" id="submitOrderBtn">\n                        Dokončit objednávku\n                        <svg class="btn-arrow" viewBox="0 0 24 24"><path d="M12 4l-1.41 1.41L16.17 11H4v2h12.17l-5.58 5.59L12 20l8-8z"></path></svg>\n                    </button>\n \n                    <div class="trust-badges">\n                        <div class="badge-item">\n                            <svg viewBox="0 0 24 24"><path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-5.45 9-12V5l-9-4zm-2 16l-4-4 1.41-1.41L10 14.17l6.59-6.59L18 9l-8 8z"></path></svg>\n                            <span>Bezpečný nákup</span>\n                        </div>\n                        <div class="badge-item">\n                            <svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"></path></svg>\n                            <span>Prodej od 18 let</span>\n                        </div>\n                    </div>\n \n                </div>\n            </div>\n \n        </div>\n    </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<style>\n  .wp-block-post-title { display: none !important; }\n</style>\n<!-- /wp:html --></div>\n<!-- /wp:group -->', 'Košík', '', 'publish', 'closed', 'closed', '', 'kosik', '', '', '2026-09-01 15:34:22', '2026-09-01 15:34:22', '', 0, 'http://medalkohol-wp.test/?page_id=12', 0, 'page', '', 0),
