	(22, 1, '2026-08-29 10:57:37', '2026-08-29 10:57:37', '<!-- wp:group {"metadata":{"patternName":"twentytwentyfive/footer","name":"Footer","description":"Footer columns with logo, title, tagline and links.","categories":["footer"]},"className":"o-sticky o-sticky-scope-main-area o-sticky-pos-top o-sticky-bhvr-keep animated zoomIn fast is-style-default","style":{"spacing":{"padding":{"top":"var:preset|spacing|60","bottom":"var:preset|spacing|50"}},"background":{"backgroundImage":{"url":"http://medalkohol-wp.test/wp-content/uploads/2026/08/medove-plastve.png","id":19,"source":"file","title":"medové plastve"},"backgroundSize":"cover"}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-group o-sticky o-sticky-scope-main-area o-sticky-pos-top o-sticky-bhvr-keep animated zoomIn fast is-style-default" style="padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--50)"><!-- wp:site-logo {"width":245,"shouldSyncIcon":true,"align":"center","className":"is-style-rounded","style":{"spacing":{"padding":{"right":"0","left":"0"},"margin":{"top":"-50px","left":"0px","bottom":"-15px"}}}} /-->\n\n<!-- wp:group {"align":"wide","layout":{"type":"default"}} -->\n<div class="wp-block-group alignwide"><!-- wp:site-title {"level":2,"style":{"typography":{"textAlign":"center"},"color":{"gradient":"linear-gradient(135deg,rgba(255,227,71,0.52) 0%,rgba(255,61,61,0.42) 100%)"}}} /-->\n\n<!-- wp:social-links {"iconColor":"base","iconColorValue":"#FFFFFF","iconBackgroundColor":"contrast","iconBackgroundColorValue":"#111111","align":"center"} -->\n<ul class="wp-block-social-links aligncenter has-icon-color has-icon-background-color"><!-- wp:social-link {"url":"https://www.facebook.com/profile.php?id=61574313534732","service":"facebook"} /-->\n\n<!-- wp:social-link {"url":"https://www.instagram.com/medarna.liskovec?igsi=aDhscWE5ZDFxMTBj","service":"instagram"} /-->\n\n<!-- wp:social-link {"url":"https://www.tiktok.com/@medarnaliskovec?_r=1\\u0026_t=ZN-99HkuAarEtq","service":"tiktok"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->', 'Footer', '', 'inherit', 'closed', 'closed', '', '20-revision-v1', '', '', '2026-08-29 10:57:37', '2026-08-29 10:57:37', '', 20, 'http://medalkohol-wp.test/?p=22', 0, 'revision', '', 0),
	(23, 1, '2026-08-29 11:13:21', '2026-08-29 11:13:21', '<!-- wp:group {"metadata":{"patternName":"twentytwentyfive/header","name":"Header","description":"Site header with site title and navigation.","categories":["header"]},"align":"full","layout":{"type":"default"}} -->\n<div class="wp-block-group alignfull"><!-- wp:html -->\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Header - Medárna Lískovec</title>\n\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="">\n<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@600;700&amp;family=Montserrat:wght@400;500;600;700&amp;display=swap" rel="stylesheet">\n\n<style>\n* {\n    box-sizing: border-box;\n    margin: 0;\n    padding: 0;\n}\n\nbody {\n    background-color: #0f0206;\n    font-family: \'Montserrat\', sans-serif;\n    color: #ebd7af;\n}\n\n.site-header {\n    background: linear-gradient(180deg, #380512 0%, #1e030a 100%);\n    border-bottom: 1px solid rgba(212, 175, 55, 0.3);\n    padding: 14px 6%;\n    position: sticky;\n    top: 0;\n    z-index: 1000;\n    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6);\n}\n\n.header-container {\n    max-width: 1200px;\n    margin: 0 auto;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.brand-logo-link {\n    display: inline-flex;\n    align-items: center;\n    gap: 14px;\n    text-decoration: none;\n    transition: opacity 0.3s ease, transform 0.3s ease;\n}\n\n.brand-logo-link:hover {\n    opacity: 0.9;\n    transform: translateY(-1px);\n}\n\n.bee-icon {\n    width: 64px;\n    height: 64px;\n    border: 3px solid #d4af37;\n    border-radius: 50%;\n    padding: 4px;\n    object-fit: cover;\n    display: block;\n    flex-shrink: 0;\n    box-shadow: 0 0 10px rgba(212, 175, 55, 0.25);\n}\n\n.brand-name {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 1.7rem;\n    font-weight: 700;\n    letter-spacing: 1.8px;\n    text-transform: uppercase;\n    background: linear-gradient(135deg, #fff3d1 0%, #d4af37 60%, #aa8222 100%);\n    -webkit-background-clip: text;\n    -webkit-text-fill-color: transparent;\n    line-height: 1;\n    white-space: nowrap;\n}\n\n.nav-actions {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n}\n\n.nav-btn {\n    display: inline-block;\n    text-decoration: none;\n    font-size: 0.8rem;\n    font-weight: 600;\n    letter-spacing: 1.5px;\n    text-transform: uppercase;\n    padding: 10px 24px;\n    border-radius: 2px;\n    transition: all 0.3s ease;\n    white-space: nowrap;\n}\n\n.nav-btn-secondary {\n    color: #ebd7af;\n    border: 1px solid rgba(212, 175, 55, 0.4);\n    background: rgba(212, 175, 55, 0.05);\n}\n\n.nav-btn-secondary:hover {\n    color: #ffffff;\n    border-color: #d4af37;\n    background: rgba(212, 175, 55, 0.15);\n    transform: translateY(-1px);\n}\n\n.nav-btn-primary {\n    background: linear-gradient(135deg, #d4af37 0%, #b38f2d 100%);\n    color: #1e030a;\n    box-shadow: 0 2px 10px rgba(212, 175, 55, 0.2);\n}\n\n.nav-btn-primary:hover {\n    background: #ffffff;\n    color: #1e030a;\n    box-shadow: 0 0 15px rgba(255, 255, 255, 0.4);\n    transform: translateY(-1px);\n}\n\n@media (max-width: 850px) {\n    .header-container {\n        flex-direction: column;\n        gap: 16px;\n    }\n\n    .brand-name {\n        font-size: 1.4rem;\n    }\n\n    .bee-icon {\n        width: 54px;\n        height: 54px;\n    }\n\n    .nav-actions {\n        gap: 12px;\n        flex-wrap: wrap;\n        justify-content: center;\n    }\n\n    .nav-btn {\n        padding: 8px 18px;\n        font-size: 0.75rem;\n    }\n}\n</style>\n\n<header class="site-header">\n    <div class="header-container">\n\n        <a href="/" class="brand-logo-link" title="Medárna Lískovec">\n            <img src="https://raw.githubusercontent.com/Pahi25/Medak/refs/heads/main/bee.jpg" alt="Bee" class="bee-icon">\n            <span class="brand-name">Medárna Lískovec</span>\n        </a>\n\n        <nav class="nav-actions">\n            <a href="https://www.medalkohol.cz/" class="nav-btn nav-btn-secondary">Domů</a>\n            <a href="https://www.medalkohol.cz/#produkt" class="nav-btn nav-btn-secondary">Produkt</a>\n            <a href="https://www.medalkohol.cz/kosik" id="kosik" class="nav-btn nav-btn-secondary">Košík</a>\n            <a href="https://www.medalkohol.cz/#kontakt" class="nav-btn nav-btn-primary">Kontakty</a>\n        </nav>\n\n    </div>\n</header>\n<!-- /wp:html --></div>\n<!-- /wp:group -->', 'Header', '', 'publish', 'closed', 'closed', '', 'header', '', '', '2026-08-30 13:41:27', '2026-08-30 13:41:27', '', 0, 'http://medalkohol-wp.test/?p=23', 0, 'wp_template_part', '', 0),
	(24, 1, '2026-08-29 11:14:46', '2026-08-29 11:14:46', '<!-- wp:group {"metadata":{"patternName":"twentytwentyfive/header","name":"Header","description":"Site header with site title and navigation.","categories":["header"]},"align":"full","layout":{"type":"default"}} -->\n<div class="wp-block-group alignfull"><!-- wp:html -->\n<!DOCTYPE html>\n<html lang="cs">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Header - Medárna Lískovec</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@600;700&family=Montserrat:wght@400;600&display=swap" rel="stylesheet">\n    \n    <style>\n        * {\n            box-sizing: border-box;\n            margin: 0;\n            padding: 0;\n        }\n\n        body {\n            background-color: #0f0206;\n            font-family: \'Montserrat\', sans-serif;\n        }\n\n        /* Kompaktní hlavička */\n        .site-header {\n            background: linear-gradient(180deg, #380512 0%, #1e030a 100%);\n            border-bottom: 1px solid rgba(212, 175, 55, 0.25);\n            padding: 16px 6%;\n            position: sticky;\n            top: 0;\n            z-index: 1000;\n            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);\n        }\n\n        .header-container {\n            max-width: 1200px;\n            margin: 0 auto;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n        }\n\n        /* Logo Medárny */\n        .brand-logo {\n            font-family: \'Cormorant Garamond\', serif;\n            font-size: 1.8rem;\n            font-weight: 700;\n            letter-spacing: 2px;\n            text-transform: uppercase;\n            text-decoration: none;\n            background: linear-gradient(135deg, #fff3d1 0%, #d4af37 60%, #aa8222 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            transition: opacity 0.3s ease;\n        }\n\n        .brand-logo:hover {\n            opacity: 0.85;\n        }\n\n        /* Hlavní navigace */\n        .nav-menu {\n            display: flex;\n            gap: 32px;\n            list-style: none;\n        }\n\n        .nav-link {\n            text-decoration: none;\n            color: #ebd7af;\n            font-size: 0.8rem;\n            font-weight: 600;\n            letter-spacing: 1.8px;\n            text-transform: uppercase;\n            transition: color 0.3s ease;\n            position: relative;\n            padding-bottom: 4px;\n        }\n\n        .nav-link:hover {\n            color: #ffffff;\n        }\n\n        .nav-link::after {\n            content: \'\';\n            position: absolute;\n            bottom: 0;\n            left: 0;\n            width: 0;\n            height: 1px;\n            background-color: #d4af37;\n            transition: width 0.3s ease;\n        }\n\n        .nav-link:hover::after {\n            width: 100%;\n        }\n\n        /* Tlačítko */\n        .header-btn {\n            background: linear-gradient(135deg, #d4af37 0%, #b38f2d 100%);\n            color: #1e030a;\n            text-decoration: none;\n            font-size: 0.75rem;\n            font-weight: 600;\n            letter-spacing: 1.5px;\n            text-transform: uppercase;\n            padding: 10px 22px;\n            border-radius: 2px;\n            transition: all 0.3s ease;\n            box-shadow: 0 2px 10px rgba(212, 175, 55, 0.2);\n        }\n\n        .header-btn:hover {\n            background: #ffffff;\n            color: #1e030a;\n            box-shadow: 0 0 15px rgba(255, 255, 255, 0.4);\n            transform: translateY(-1px);\n        }\n\n        /* Mobilní přizpůsobení */\n        @media (max-width: 768px) {\n            .header-container {\n                flex-direction: column;\n                gap: 16px;\n            }\n\n            .nav-menu {\n                gap: 18px;\n            }\n        }\n    </style>\n</head>\n<body>\n\n    <header class="site-header">\n        <div class="header-container">\n            <a href="/" class="brand-logo">Medárna Lískovec</a>\n\n            <nav>\n                <ul class="nav-menu">\n                    <li><a href="#o-nas" class="nav-link">O nás</a></li>\n                    <li><a href="#produkty" class="nav-link">Produkty</a></li>\n                    <li><a href="#kontakt" class="nav-link">Kontakt</a></li>\n                </ul>\n            </nav>\n\n            <a href="#eshop" class="header-btn">E-shop</a>\n        </div>\n    </header>\n\n</body>\n</html>\n<!-- /wp:html --></div>\n<!-- /wp:group -->', 'Header', '', 'inherit', 'closed', 'closed', '', '23-revision-v1', '', '', '2026-08-29 11:14:46', '2026-08-29 11:14:46', '', 23, 'http://medalkohol-wp.test/?p=24', 0, 'revision', '', 0),
